      "proposed_laureates": [
        "Masashi Yanagisawa",
        "Luis de Lecea",
        "Emmanuel Mignot"
      ],
      "assessment": {
        "nobel_worthiness": "The orexin system gave a compelling molecular and physiological explanation for stabilization of wakefulness and a central cause of narcolepsy.",
        "attribution": "Yanagisawa and de Lecea independently identified the peptide system, and Mignot provided decisive connection to human narcolepsy.",
        "maturity": "Genetic, physiological, and clinical evidence has converged, with therapeutic consequences reinforcing the discovery's importance.",
        "uncertainties": [
          "Several investigators made closely related foundational contributions, making a three-person selection difficult."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Steven A. Rosenberg",
        "Carl H. June",
        "Michel Sadelain"
      ],
      "assessment": {
        "nobel_worthiness": "CAR-T therapy established that engineered immune cells can produce profound, durable responses in otherwise refractory cancers.",
        "attribution": "Rosenberg pioneered adoptive-cell therapy, while June and Sadelain made central contributions to clinically effective CAR-T design and development.",
        "maturity": "Approved treatments and extensive clinical experience demonstrate a durable medical advance, although benefit remains uneven among cancers.",
        "uncertainties": [
          "The contribution is a long translational continuum with substantial additional technical and clinical contributors."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Terje Lømo",
        "Timothy V. P. Bliss",
        "Richard G. M. Morris"
      ],
      "assessment": {
        "nobel_worthiness": "Long-term potentiation supplied a durable physiological framework for activity-dependent synaptic change and learning.",
        "attribution": "Lømo and Bliss made the foundational observations, and Morris provided influential evidence linking synaptic plasticity to memory.",
        "maturity": "The phenomenon and its mechanistic importance have been extensively reproduced and elaborated over decades.",
        "uncertainties": [
          "The precise extent to which LTP explains memory in intact brains remains an active conceptual question."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Nicholas B. Lydon",
        "Brian J. Druker",
        "Charles L. Sawyers"
      ],
      "assessment": {
        "nobel_worthiness": "BCR-ABL inhibition showed that understanding a cancer-driving lesion could yield a highly effective molecularly targeted treatment.",
        "attribution": "Lydon was central to inhibitor development, Druker to clinical translation, and Sawyers to defining resistance and subsequent therapeutic advances.",
        "maturity": "Long-term clinical success in chronic myeloid leukemia makes this a mature landmark in precision oncology.",
        "uncertainties": [
          "The formulation necessarily compresses contributions from target discovery, medicinal chemistry, and clinical development."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Y. M. Dennis Lo"
      ],
      "assessment": {
        "nobel_worthiness": "Fetal cell-free DNA transformed prenatal screening by enabling noninvasive access to fetal genetic information from maternal blood.",
        "attribution": "Lo is directly and distinctly associated with the key discovery and its clinical development.",
        "maturity": "The approach is broadly implemented and its performance and clinical role have been tested at scale.",
        "uncertainties": [
          "Screening implementation raises ethical and health-system questions that are separate from the underlying discovery."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B037",
      "proposed_laureates": [
        "Adrian R. Krainer",
        "C. Frank Bennett"
      ],
      "assessment": {
        "nobel_worthiness": "Antisense correction of SMN2 splicing provided a decisive therapeutic strategy for spinal muscular atrophy and demonstrated the power of RNA medicines.",
        "attribution": "Krainer's splicing research and Bennett's antisense-therapeutics leadership represent complementary essential contributions.",
        "maturity": "Clinical efficacy, including major benefit in early-treated patients, has firmly established the principle.",
        "uncertainties": [
          "The therapeutic result depends on a wider network of genetic, preclinical, and clinical contributors."
        ]
      }
    }
